shape=[(0,2),(1,1),(2,1),(2,2),(3,0),(3,1),(4,2),(4,3)]  # offsets of 5s from (8,6)
H,W=len(grid),len(grid[0])
def match_at(r0,c0):
    cells=[]
    for dr,dc in shape:
        r,c=r0+dr,c0+dc
        if not(0<=r<H and 0<=c<W): return None
        if grid[r][c]!=0: return None
        cells.append((r,c))
    return cells
hits=[]
for r in range(H):
    for c in range(W):
        m=match_at(r,c)
        if m: hits.append(m)
# also try anchored so shape cells all 0, print bounding boxes
for m in hits:
    rs=[x[0] for x in m]; cs=[x[1] for x in m]
    print(min(rs),min(cs),max(rs),max(cs),m)

out=[row[:] for row in grid]
for m in hits:
    for r,c in m: out[r][c]=5
for row in out: print(' '.join(map(str,row)))
